PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sheets(id INTEGER PRIMARY KEY, channel_id INTEGER NOT NULL REFERENCES channels(id), spreadsheet_id TEXT NOT NULL UNIQUE, range_name TEXT NOT NULL, mapping TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, last_attempt TEXT, last_success TEXT);
CREATE TABLE IF NOT EXISTS entries(id INTEGER PRIMARY KEY, sheet_id INTEGER NOT NULL REFERENCES sheets(id), external_id TEXT NOT NULL, occurred TEXT NOT NULL, stake REAL NOT NULL CHECK(stake>0), profit REAL NOT NULL, UNIQUE(sheet_id,external_id));
CREATE TABLE IF NOT EXISTS revisions(id INTEGER PRIMARY KEY, entry_id INTEGER NOT NULL REFERENCES entries(id), previous TEXT NOT NULL, changed TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_logs(id INTEGER PRIMARY KEY, sheet_id INTEGER REFERENCES sheets(id), started TEXT NOT NULL, status TEXT NOT NULL, message TEXT NOT NULL);
